"""End-to-end: data generated by the model itself must be learned and predicted well."""

import warnings

import numpy as np
import pytest
from scipy.stats import spearmanr

from cases import n
from skillgraph import TS1, Match


@pytest.mark.slow
def test_large_free_for_alls_issue_23():
    """Issue #23 setup (big FFAs, no draws, beta = sigma/4): ratings must track
    true skill and finishing positions, with no poor finisher near the top."""
    rng = np.random.default_rng(23)
    env = TS1(draw_probability=0.0, beta=25 / 3 / 4)
    players = n(600, 2000)
    true = rng.normal(25, 25 / 3, players)
    ratings = {i: env.create_rating() for i in range(players)}
    pct = {i: [] for i in range(players)}
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        for _ in range(n(60, 150)):
            size = int(rng.choice([50, 120, 300]))
            ids = rng.choice(players, size=size, replace=False)
            order = ids[np.argsort(-(true[ids] + rng.normal(0, env.beta, size)))]
            place = {p: r for r, p in enumerate(order)}
            out = env.rate([[ratings[p]] for p in ids], ranks=[place[p] for p in ids])
            for p, (r,) in zip(ids, out):
                ratings[p] = r
                pct[p].append(place[p] / (size - 1))
    played = [i for i in range(players) if len(pct[i]) >= 3]
    mus = np.array([ratings[i].mu for i in played])
    avg = np.array([np.mean(pct[i]) for i in played])
    assert spearmanr(mus, true[played]).statistic > 0.97
    assert spearmanr(mus, -avg).statistic > 0.97
    top = np.argsort(-mus)[: max(1, len(played) // 20)]
    assert np.sum(avg[top] > 0.5) == 0


@pytest.mark.slow
def test_calibration_and_recovery():
    rng = np.random.default_rng(1)
    env = TS1(draw_probability=0.15)
    players = 300
    true = rng.normal(25, 25 / 3, players)
    formats = {"1v1": [1, 1], "2v2": [2, 2], "1v2": [1, 2], "ffa3": [1, 1, 1]}
    matches, scored = [], []
    for g in range(n(12000, 40000)):
        sizes = formats[rng.choice(list(formats))]
        ids = rng.choice(players, size=sum(sizes), replace=False).tolist()
        teams, i = [], 0
        for s in sizes:
            teams.append(ids[i : i + s])
            i += s
        perf = [sum(true[p] + rng.normal(0, env.beta) for p in t) for t in teams]
        order = np.argsort(perf)[::-1]
        ranks, r = [0] * len(teams), 0
        for k in range(1, len(order)):
            a, b = order[k - 1], order[k]
            if perf[a] - perf[b] > env.draw_margin(len(teams[a]) + len(teams[b])):
                r += 1
            ranks[b] = r
        matches.append(Match(teams, ranks))
        scored.append(len(teams) == 2 and g > len(matches) // 3)
    ratings = env.rate_matches(matches).ratings

    # Calibration of the realized-outcome probability on 2-team matches:
    # E[1/p(outcome)] style checks are noisy, so test the win event directly.
    preds, wins, draws, pdraw = [], [], [], []
    rr = {}
    for m, use in zip(matches, scored):
        teams = [[rr.get(p, env.create_rating()) for p in t] for t in m.teams]
        if use:
            preds.append(env.outcome_probability(teams, [0, 1]))
            pdraw.append(env.outcome_probability(teams, [0, 0]))
            wins.append(m.ranks[0] < m.ranks[1])
            draws.append(m.ranks[0] == m.ranks[1])
        for ids, new in zip(m.teams, env.rate(teams, m.ranks)):
            for p, r in zip(ids, new):
                rr[p] = r
    preds, wins = np.array(preds), np.array(wins, float)
    for lo in np.arange(0, 1, 0.1):
        sel = (preds >= lo) & (preds < lo + 0.1)
        if sel.sum() >= 200:
            se = np.sqrt(preds[sel].mean() * (1 - preds[sel].mean()) / sel.sum())
            assert abs(preds[sel].mean() - wins[sel].mean()) < 4 * se + 0.01, (lo, preds[sel].mean(), wins[sel].mean())
    pdraw, draws = np.array(pdraw), np.array(draws, float)
    se = np.sqrt(pdraw.mean() * (1 - pdraw.mean()) / len(draws))
    assert abs(pdraw.mean() - draws.mean()) < 4 * se

    mus = np.array([ratings[p].mu for p in range(players)])
    sig = np.array([ratings[p].sigma for p in range(players)])
    assert spearmanr(mus, true).statistic > 0.97
    z = np.abs(true - mus) / sig
    # TS1 is known to be somewhat overconfident (it ignores correlations
    # between players' posteriors); 2-sigma coverage should still be near 95%.
    assert 0.90 < np.mean(z < 2) < 0.99
